   CombatAccess.set(actor,"mp",11);Object above=CombatAccess.call(actor,"drainManaIfStrictlyAbove","(II)Llocal/lito381/server/"+name.split("\\$")[0]+"$ManaDrain;",100,10);check(number(above,"drained")==10&&number(above,"afterMp")==1&&(int)CombatAccess.field(actor,"mp")==1,"actual native MP debit result, never estimated success");
   Object below=CombatAccess.call(actor,"drainManaIfStrictlyAbove","(II)Llocal/lito381/server/"+name.split("\\$")[0]+"$ManaDrain;",100,10);check(number(below,"drained")==0&&(int)CombatAccess.field(actor,"mp")==1,"insufficient MP leaves native state intact");
   CombatAccess.set(actor,"hp",0);Object dead=CombatAccess.call(actor,"drainManaIfStrictlyAbove","(II)Llocal/lito381/server/"+name.split("\\$")[0]+"$ManaDrain;",100,1);check(dead==null&&(int)CombatAccess.field(actor,"mp")==1,"dead actor cannot debit MP");
   CombatAccess.set(actor,"hp",1);boolean mismatch=false;try{CombatAccess.call(actor,"drainManaIfStrictlyAbove","(II)Llocal/lito381/server/"+name.split("\\$")[0]+"$ManaDrain;",101,1);}catch(IllegalStateException expected){mismatch=true;}check(mismatch&&(int)CombatAccess.field(actor,"mp")==1,"native maximum-MP mismatch fails without debit");
   boolean bone=(boolean)CombatAccess.call(actor,"activateBoneBreak","(JI)Z",now,2);Object lease=CombatAccess.field(actor,"nativeSourceSpecialBoneLease");long expiry=(long)CombatAccess.field(actor,"boneBreakExpiresAtNanos");check(bone&&lease!=null&&expiry==now+2_000_000_000L,"actual original Bone writer publishes its status lease");
